using System;using System.Data;using System.Linq;using System.Web;using Newtonsoft.Json;
namespace AQOONHUB_SMS.Modules.Communication{public partial class Overview:CommunicationPageBase{protected void Page_Load(object s,EventArgs e){if(IsPostBack)return;try{DataRow n=Repo.OverviewTotals(UserId).Rows[0];litAnnouncements.Text=H(n["TotalAnnouncements"]);litUnread.Text=H(n["UnreadMessages"]);litSms.Text=H(n["SmsSent"]);litEmail.Text=H(n["EmailsSent"]);litFailed.Text=H(n["FailedDeliveries"]);DataTable t=Repo.DeliveryTrend();gvTrend.DataSource=t;gvTrend.DataBind();hidTrendLabels.Value=JsonConvert.SerializeObject(t.AsEnumerable().Select(x=>Convert.ToDateTime(x["D"]).ToString("dd MMM")));hidDelivered.Value=JsonConvert.SerializeObject(t.AsEnumerable().Select(x=>Convert.ToInt32(x["Delivered"])));hidFailedChart.Value=JsonConvert.SerializeObject(t.AsEnumerable().Select(x=>Convert.ToInt32(x["Failed"])));DataTable c=Repo.ChannelTotals();hidChannelLabels.Value=JsonConvert.SerializeObject(c.AsEnumerable().Select(x=>Convert.ToString(x["Channel"])));hidChannelValues.Value=JsonConvert.SerializeObject(c.AsEnumerable().Select(x=>Convert.ToInt32(x["Total"])));DataTable z=Repo.StatusTotals();hidStatusLabels.Value=JsonConvert.SerializeObject(z.AsEnumerable().Select(x=>Convert.ToString(x["Status"])));hidStatusValues.Value=JsonConvert.SerializeObject(z.AsEnumerable().Select(x=>Convert.ToInt32(x["Total"])));DataTable r=Repo.Recent();rpRecent.DataSource=r;rpRecent.DataBind();pnlRecentEmpty.Visible=r.Rows.Count==0;gvUpcoming.DataSource=Repo.Upcoming();gvUpcoming.DataBind();}catch(Exception){litMessage.Text="<div class='comm-error' role='alert'>Communication data is temporarily unavailable. Confirm the module migration and database connection, then retry.</div>";}}}}
